//! Canonical dimension expressions and their unification.
//!
//! A dimension is an element of the free abelian group generated by the base
//! dimensions plus the dimension variables currently in scope (spec §4.2).
//! The canonical form is a map from generator to a non-zero rational exponent,
//! so equality is structural equality of the map and `L/T` is literally the
//! same value as `L*T^-1`.
//!
//! The module also carries the base/alias environment used to parse and print
//! dimension expressions (`L`, `Length`, `Energy`, ...).

use crate::rat::format_rational;
use crate::rat::parse_decimal;
use indexmap::IndexMap;
use num_bigint::BigInt;
use num_rational::BigRational;
use num_traits::One;
use num_traits::Signed;
use num_traits::Zero;
use std::collections::BTreeMap;
use std::collections::HashMap;
use std::fmt;

/// One generator of the dimension group.
///
/// SI/host base dimensions use canonical names. Source declarations use a
/// nominal owner and declaration name, independent of import/display aliases.
/// Variables use a numeric id allocated by the type checker.
#[derive(
    Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Debug, serde::Serialize, serde::Deserialize,
)]
pub enum Atom {
    /// An SI or host base dimension such as `Length` or a host-defined `Currency`.
    Base(Box<str>),
    /// A source-owned base dimension. Its readable spelling is not its identity.
    Nominal(NominalBase),
    /// A dimension variable introduced by `<d>` or by inference.
    Var(u32),
}

/// A base dimension declared in a particular source/module owner.
///
/// Ownership and declaration name determine equality, order and hashing. An
/// import may change the display hint without creating a new generator.
#[derive(Clone, Debug, serde::Serialize, serde::Deserialize)]
pub struct NominalBase {
    owner: Box<str>,
    name: Box<str>,
    display: Box<str>,
}
impl NominalBase {
    /// A canonical declaration owner plus its declared name.
    #[must_use]
    pub fn new(
        owner: impl Into<Box<str>>,
        name: impl Into<Box<str>>,
    ) -> Self {
        let name = name.into();
        Self {
            owner: owner.into(),
            display: name.clone(),
            name,
        }
    }

    /// The canonical defining module/source identity.
    #[must_use]
    pub fn owner(&self) -> &str {
        &self.owner
    }

    /// The declaration name, independent of import aliases.
    #[must_use]
    pub fn name(&self) -> &str {
        &self.name
    }

    /// The current readable hint, excluded from equality and hashing.
    #[must_use]
    pub fn display_name(&self) -> &str {
        &self.display
    }

    /// Clone this generator with a different readable hint.
    #[must_use]
    pub fn with_display(
        &self,
        display: impl Into<Box<str>>,
    ) -> Self {
        Self {
            display: display.into(),
            ..self.clone()
        }
    }

    /// Versioned, owned transport spelling. Display aliases are excluded.
    #[must_use]
    pub fn transport_name(&self) -> String {
        format!("{NOMINAL_PREFIX}{}_{}", hex(&self.owner), hex(&self.name))
    }
}
impl PartialEq for NominalBase {
    fn eq(
        &self,
        other: &Self,
    ) -> bool {
        self.owner == other.owner && self.name == other.name
    }
}
impl Eq for NominalBase {}
impl PartialOrd for NominalBase {
    fn partial_cmp(
        &self,
        other: &Self,
    ) -> Option<std::cmp::Ordering> {
        Some(self.cmp(other))
    }
}
impl Ord for NominalBase {
    fn cmp(
        &self,
        other: &Self,
    ) -> std::cmp::Ordering {
        (&self.owner, &self.name).cmp(&(&other.owner, &other.name))
    }
}
impl std::hash::Hash for NominalBase {
    fn hash<H: std::hash::Hasher>(
        &self,
        state: &mut H,
    ) {
        self.owner.hash(state);
        self.name.hash(state);
    }
}
const TRANSPORT_PREFIX: &str = "__aevia_dim_";
const NOMINAL_PREFIX: &str = "__aevia_dim_n_v1_";
const RAW_PREFIX: &str = "__aevia_dim_b_v1_";
const VARIABLE_PREFIX: &str = "__aevia_dim_v_v1_";
fn hex(text: &str) -> String {
    const DIGITS: &[u8; 16] = b"0123456789abcdef";
    let mut encoded = String::with_capacity(text.len() * 2);
    for byte in text.bytes() {
        encoded.push(char::from(DIGITS[usize::from(byte >> 4)]));
        encoded.push(char::from(DIGITS[usize::from(byte & 15)]));
    }
    encoded
}
fn unhex(text: &str) -> Option<String> {
    if !text.len().is_multiple_of(2) {
        return None;
    }
    let bytes: Option<Vec<u8>> = text
        .as_bytes()
        .as_chunks::<2>()
        .0
        .iter()
        .map(|pair| {
            let a = char::from(pair[0]).to_digit(16)?;
            let b = char::from(pair[1]).to_digit(16)?;
            Some((a * 16 + b) as u8)
        })
        .collect();
    String::from_utf8(bytes?).ok()
}

impl Atom {
    fn base(name: &str) -> Self {
        Self::Base(name.into())
    }

    /// A kernel `DimExpr::Base` spelling, independent of display aliases.
    /// Ordinary host base names keep their existing spelling. Reserved raw
    /// names are escaped so they cannot be mistaken for a nominal generator.
    #[must_use]
    pub fn transport_name(&self) -> Option<String> {
        match self {
            | Self::Base(name) if name.starts_with(TRANSPORT_PREFIX) => {
                Some(format!("{RAW_PREFIX}{}", hex(name)))
            },
            | Self::Base(name) => Some(name.to_string()),
            | Self::Nominal(base) => Some(base.transport_name()),
            | Self::Var(_) => None,
        }
    }

    /// Decode an owned base spelling, preserving unrecognized host names.
    #[must_use]
    pub fn from_transport_base(name: &str) -> Self {
        if let Some(encoded) = name.strip_prefix(NOMINAL_PREFIX)
            && let Some((owner, name)) = encoded.split_once('_')
            && let (Some(owner), Some(name)) = (unhex(owner), unhex(name))
        {
            return Self::Nominal(NominalBase::new(owner, name));
        }
        if let Some(raw) = name.strip_prefix(RAW_PREFIX).and_then(unhex) {
            return Self::Base(raw.into());
        }
        Self::base(name)
    }
}

impl fmt::Display for Atom {
    fn fmt(
        &self,
        f: &mut fmt::Formatter<'_>,
    ) -> fmt::Result {
        match self {
            | Self::Base(name) => f.write_str(name),
            | Self::Nominal(base) => f.write_str(base.display_name()),
            | Self::Var(id) => write!(f, "d{id}"),
        }
    }
}

/// A dimension expression in canonical form.
///
/// The map never stores zero exponents, so the empty map is exactly the
/// dimensionless dimension `1`.
///
/// The representation is shared: a sorted slice of generator/exponent pairs
/// behind an `Arc`, with `None` for `1`. Every scalar value at run time
/// carries its dimension (§9.2.3), so cloning one must not copy a map, and
/// `1` must not allocate. Products and quotients of the same two dimensions
/// recur on every step of a numeric loop, so they are memoized per thread.
#[derive(Clone, Default)]
pub struct Dim {
    factors: Option<std::sync::Arc<[(Atom, BigRational)]>>,
}

impl serde::Serialize for Dim {
    fn serialize<S: serde::Serializer>(
        &self,
        serializer: S,
    ) -> Result<S::Ok, S::Error> {
        serializer.collect_seq(self.slice().iter().map(|(atom, exp)| (atom, exp)))
    }
}

impl<'de> serde::Deserialize<'de> for Dim {
    fn deserialize<D: serde::Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        let factors: Vec<(Atom, BigRational)> = serde::Deserialize::deserialize(deserializer)?;
        Ok(Self::from_factors(factors))
    }
}

impl PartialEq for Dim {
    fn eq(
        &self,
        other: &Self,
    ) -> bool {
        match (&self.factors, &other.factors) {
            | (None, None) => true,
            | (Some(a), Some(b)) => std::sync::Arc::ptr_eq(a, b) || a[..] == b[..],
            | _ => false,
        }
    }
}

impl Eq for Dim {}

impl std::hash::Hash for Dim {
    fn hash<H: std::hash::Hasher>(
        &self,
        state: &mut H,
    ) {
        self.slice().hash(state);
    }
}

/// Which memoized binary operation a cache entry answers.
#[derive(Clone, Copy, PartialEq, Eq, Hash)]
enum DimOp {
    Mul,
    Div,
}

type DimMemo = HashMap<(usize, usize, DimOp), (Dim, Dim, Dim)>;

thread_local! {
    /// Products and quotients of shared dimensions, keyed by the operands'
    /// addresses. Each entry keeps both operands alive, so an address in a key
    /// cannot be reused by a different dimension while the entry exists.
    static DIM_MEMO: std::cell::RefCell<DimMemo> = std::cell::RefCell::new(HashMap::new());
}

const DIM_MEMO_CAPACITY: usize = 4096;

impl Dim {
    fn slice(&self) -> &[(Atom, BigRational)] {
        self.factors.as_deref().unwrap_or(&[])
    }

    fn from_map(map: BTreeMap<Atom, BigRational>) -> Self {
        if map.is_empty() {
            return Self { factors: None };
        }
        Self {
            factors: Some(map.into_iter().collect::<Vec<_>>().into()),
        }
    }

    fn address(&self) -> usize {
        self.factors
            .as_ref()
            .map_or(0, |factors| factors.as_ptr() as usize)
    }

    fn memoized(
        &self,
        other: &Self,
        op: DimOp,
        compute: impl FnOnce() -> Self,
    ) -> Self {
        let key = (self.address(), other.address(), op);
        if let Some(hit) =
            DIM_MEMO.with(|memo| memo.borrow().get(&key).map(|entry| entry.2.clone()))
        {
            return hit;
        }
        let result = compute();
        DIM_MEMO.with(|memo| {
            let mut memo = memo.borrow_mut();
            if memo.len() >= DIM_MEMO_CAPACITY {
                memo.clear();
            }
            memo.insert(key, (self.clone(), other.clone(), result.clone()));
        });
        result
    }

    fn combine(
        &self,
        other: &Self,
        sign: i8,
    ) -> Self {
        let mut factors: BTreeMap<Atom, BigRational> = self.slice().iter().cloned().collect();
        for (atom, exponent) in other.slice() {
            let entry = factors
                .entry(atom.clone())
                .or_insert_with(BigRational::zero);
            if sign > 0 {
                *entry += exponent;
            } else {
                *entry -= exponent;
            }
        }
        factors.retain(|_, exponent| !exponent.is_zero());
        Self::from_map(factors)
    }

    /// The dimensionless dimension `1`.
    #[must_use]
    pub fn one() -> Self {
        Self::default()
    }

    /// A single base dimension, e.g. `Dim::base("Length")`.
    #[must_use]
    pub fn base(name: &str) -> Self {
        Self::from_factors([(Atom::base(name), BigRational::one())])
    }

    /// A base generator owned by a source/module identity.
    #[must_use]
    pub fn nominal_base(
        owner: impl Into<Box<str>>,
        name: impl Into<Box<str>>,
    ) -> Self {
        Self::from_factors([(
            Atom::Nominal(NominalBase::new(owner, name)),
            BigRational::one(),
        )])
    }

    /// Decode a kernel base name. Only the versioned reserved representation
    /// denotes a source-owned generator; `Base("Credit")` remains a host base.
    #[must_use]
    pub fn from_transport_base(name: &str) -> Self {
        Self::from_factors([(Atom::from_transport_base(name), BigRational::one())])
    }

    /// Give a directly named nominal base an import-local display hint. Derived
    /// products keep their individual generator names and exact exponents.
    #[must_use]
    pub fn with_display_name(
        &self,
        display: &str,
    ) -> Self {
        if self.slice().len() == 1
            && let Some((Atom::Nominal(base), exponent)) = self.slice().first()
            && exponent.is_one()
        {
            return Self::from_factors([(
                Atom::Nominal(base.with_display(display)),
                exponent.clone(),
            )]);
        }
        self.clone()
    }

    /// Relabel selected nominal generators without changing their identity.
    #[must_use]
    pub fn with_display_names(
        &self,
        names: &HashMap<NominalBase, String>,
    ) -> Self {
        Self::from_factors(self.slice().iter().map(|(atom, power)| {
            let atom = match atom {
                | Atom::Nominal(base) => {
                    names.get(base).map_or_else(
                        || atom.clone(),
                        |name| Atom::Nominal(base.with_display(name.as_str())),
                    )
                },
                | _ => atom.clone(),
            };
            (atom, power.clone())
        }))
    }

    /// A single dimension variable.
    #[must_use]
    pub fn var(id: u32) -> Self {
        Self::from_factors([(Atom::Var(id), BigRational::one())])
    }

    /// Builds a dimension from generator/exponent pairs, dropping zero powers.
    #[must_use]
    pub fn from_factors<I>(factors: I) -> Self
    where
        I: IntoIterator<Item = (Atom, BigRational)>,
    {
        let mut map: BTreeMap<Atom, BigRational> = BTreeMap::new();
        for (atom, exponent) in factors {
            if exponent.is_zero() {
                continue;
            }
            let entry = map.entry(atom).or_insert_with(BigRational::zero);
            *entry += exponent;
        }
        map.retain(|_, exponent| !exponent.is_zero());
        Self::from_map(map)
    }

    /// True when the dimension is `1`.
    #[must_use]
    pub fn is_one(&self) -> bool {
        self.factors.is_none()
    }

    /// Multiplies two dimensions (exponents add).
    #[must_use]
    pub fn mul(
        &self,
        other: &Self,
    ) -> Self {
        if other.is_one() {
            return self.clone();
        }
        if self.is_one() {
            return other.clone();
        }
        self.memoized(other, DimOp::Mul, || self.combine(other, 1))
    }

    /// Divides two dimensions (exponents subtract).
    #[must_use]
    pub fn div(
        &self,
        other: &Self,
    ) -> Self {
        if other.is_one() {
            return self.clone();
        }
        if self == other {
            return Self::one();
        }
        self.memoized(other, DimOp::Div, || self.combine(other, -1))
    }

    /// Raises the dimension to a rational power.
    #[must_use]
    pub fn pow(
        &self,
        exponent: &BigRational,
    ) -> Self {
        if exponent.is_zero() || self.is_one() {
            return Self::one();
        }
        if exponent.is_one() {
            return self.clone();
        }
        let factors = self
            .slice()
            .iter()
            .map(|(atom, value)| (atom.clone(), value * exponent));
        Self::from_factors(factors)
    }

    /// The inverse dimension.
    #[must_use]
    pub fn inverse(&self) -> Self {
        self.pow(&BigRational::from_integer(BigInt::from(-1)))
    }

    /// True when the dimension contains the given variable.
    #[must_use]
    pub fn contains_var(
        &self,
        id: u32,
    ) -> bool {
        self.slice()
            .iter()
            .any(|(atom, _)| matches!(atom, Atom::Var(var) if *var == id))
    }

    /// All dimension variables occurring in the expression.
    #[must_use]
    pub fn vars(&self) -> Vec<u32> {
        self.slice()
            .iter()
            .map(|(atom, _)| atom)
            .filter_map(|atom| {
                match atom {
                    | Atom::Var(id) => Some(*id),
                    | Atom::Base(_) | Atom::Nominal(_) => None,
                }
            })
            .collect()
    }

    /// Readable base names with their exponents. These are display hints, not
    /// semantic identities; use [`Self::factors`] for transport or comparison.
    #[must_use]
    pub fn base_factors(&self) -> Vec<(&str, &BigRational)> {
        self.slice()
            .iter()
            .filter_map(|(atom, exponent)| {
                match atom {
                    | Atom::Base(name) => Some((&**name, exponent)),
                    | Atom::Nominal(base) => Some((base.display_name(), exponent)),
                    | Atom::Var(_) => None,
                }
            })
            .collect()
    }

    /// The raw generator map, in canonical order.
    pub fn factors(&self) -> impl Iterator<Item = (&Atom, &BigRational)> {
        self.slice().iter().map(|(atom, exponent)| (atom, exponent))
    }

    /// Replaces every dimension variable by its substitution, if one exists.
    ///
    /// Unmapped variables are left in place; the caller decides whether that
    /// is an error.
    #[must_use]
    pub fn substitute<F>(
        &self,
        mut lookup: F,
    ) -> Self
    where
        F: FnMut(u32) -> Option<Dim>,
    {
        if self.is_concrete() {
            return self.clone();
        }
        let mut result = Dim::one();
        for (atom, exponent) in self.slice() {
            match atom {
                | Atom::Base(_) | Atom::Nominal(_) => {
                    result = result.mul(&Dim::from_factors([(atom.clone(), exponent.clone())]));
                },
                | Atom::Var(id) => {
                    match lookup(*id) {
                        | Some(replacement) => result = result.mul(&replacement.pow(exponent)),
                        | None => {
                            result = result
                                .mul(&Dim::from_factors([(Atom::Var(*id), exponent.clone())]));
                        },
                    }
                },
            }
        }
        result
    }

    /// True when the dimension has no variables (a concrete dimension).
    #[must_use]
    pub fn is_concrete(&self) -> bool {
        !self
            .slice()
            .iter()
            .any(|(atom, _)| matches!(atom, Atom::Var(_)))
    }

    /// The difference `self / other`, used in diagnostics.
    #[must_use]
    pub fn difference(
        &self,
        other: &Self,
    ) -> Self {
        self.div(other)
    }
}

impl fmt::Debug for Dim {
    fn fmt(
        &self,
        f: &mut fmt::Formatter<'_>,
    ) -> fmt::Result {
        f.write_str(&self.to_plain_string())
    }
}

impl fmt::Display for Dim {
    fn fmt(
        &self,
        f: &mut fmt::Formatter<'_>,
    ) -> fmt::Result {
        f.write_str(&self.to_plain_string())
    }
}

impl Dim {
    /// Renders readable generator names (`Length/Time^2`) for diagnostics.
    /// Nominal names are hints; use [`Self::to_transport_string`] when identity
    /// must survive a text boundary.
    #[must_use]
    pub fn to_plain_string(&self) -> String {
        render(self, |atom| {
            match atom {
                | Atom::Base(name) => name.to_string(),
                | Atom::Nominal(base) => base.display_name().to_string(),
                | Atom::Var(id) => format!("d{id}"),
            }
        })
    }

    /// Renders with SI *symbols* (`m/s`, `m^(3/2)`, `1/T`), for value display.
    ///
    /// `aevia-core`'s value renderer uses this spelling for the suffix after a
    /// scalar or tensor element. Negative exponents move into a denominator,
    /// a product in the denominator is parenthesised, and a rational exponent is
    /// parenthesised so the text still means the same dimension: a Brownian
    /// increment is `s^(1/2)`, never `s^1` (§8.9.1). Variables keep the `d<id>`
    /// spelling so display text cannot collide with a base name.
    #[must_use]
    pub fn to_si_symbol_string(&self) -> String {
        if self.is_one() {
            return String::new();
        }
        let mut numerator = Vec::new();
        let mut denominator = Vec::new();
        for (atom, exponent) in self.slice() {
            let name = match atom {
                | Atom::Base(name) => si_symbol(name).to_string(),
                | Atom::Nominal(base) => base.display_name().to_string(),
                | Atom::Var(id) => format!("d{id}"),
            };
            let (target, magnitude) = if exponent.is_negative() {
                (&mut denominator, -exponent.clone())
            } else {
                (&mut numerator, exponent.clone())
            };
            if magnitude.is_one() {
                target.push(name);
            } else if magnitude.is_integer() {
                target.push(format!("{name}^{}", magnitude.numer()));
            } else {
                target.push(format!("{name}^({})", format_rational(&magnitude)));
            }
        }
        let numerator = if numerator.is_empty() {
            "1".to_string()
        } else {
            numerator.join("*")
        };
        match denominator.len() {
            | 0 => numerator,
            | 1 => format!("{numerator}/{}", denominator[0]),
            | _ => format!("{numerator}/({})", denominator.join("*")),
        }
    }

    /// Renders for value display, preferring a named SI derived unit.
    ///
    /// §5.4.3: a value without a display unit prints in the "best unit" —
    /// an SI derived unit (`N`, `J`, `Pa`, `V`, …) when the dimension is
    /// exactly one, otherwise the base-symbol product of
    /// [`Dim::to_si_symbol_string`]. Only exact matches are named: `1/T` is
    /// left as `1/s` (hertz and becquerel share it, and angular frequency is
    /// not `Hz`), and a product such as `N*m` is not guessed.
    #[must_use]
    pub fn to_display_si_string(&self) -> String {
        if let Some(symbol) = derived_si_symbol(self) {
            return symbol.to_string();
        }
        self.to_si_symbol_string()
    }

    /// Collision-free dimension text for opaque runtime metadata and hashing.
    /// SI spellings are unchanged; custom/nominal generators and variables are
    /// explicitly encoded. Display hints never enter this representation.
    #[must_use]
    pub fn to_transport_string(&self) -> String {
        render(self, |atom| {
            match atom {
                | Atom::Nominal(base) => base.transport_name(),
                | Atom::Base(name) if crate::SI_BASE_DIMENSIONS.contains(&name.as_ref()) => {
                    name.to_string()
                },
                | Atom::Base(name) => format!("{RAW_PREFIX}{}", hex(name)),
                | Atom::Var(id) => format!("{VARIABLE_PREFIX}{id}"),
            }
        })
    }

    /// Parse text emitted by [`Self::to_transport_string`]. This is deliberately
    /// separate from parsing source names in a module's dimension environment.
    pub fn parse_transport(text: &str) -> Result<Self, DimParseError> {
        let mut parser = DimTextParser::new(text);
        parser.transport = true;
        let dim = parser.parse_dim()?;
        parser.skip_space();
        if parser.rest().is_empty() {
            Ok(dim)
        } else {
            Err(DimParseError::Trailing(parser.rest().to_string()))
        }
    }

    /// Parses a dimension expression with canonical names.
    ///
    /// # Errors
    ///
    /// Returns [`DimParseError`] when the text is not a dimension expression.
    pub fn parse_plain(text: &str) -> Result<Self, DimParseError> {
        let mut parser = DimTextParser::new(text);
        let dim = parser.parse_dim()?;
        parser.skip_space();
        if parser.rest().is_empty() {
            Ok(dim)
        } else {
            Err(DimParseError::Trailing(parser.rest().to_string()))
        }
    }
}

fn render<F>(
    dim: &Dim,
    mut name_of: F,
) -> String
where
    F: FnMut(&Atom) -> String,
{
    if dim.is_one() {
        return "1".to_string();
    }
    let mut numerator = Vec::new();
    let mut denominator = Vec::new();
    for (atom, exponent) in dim.slice() {
        let name = name_of(atom);
        let (target, magnitude) = if exponent.is_negative() {
            (&mut denominator, -exponent.clone())
        } else {
            (&mut numerator, exponent.clone())
        };
        if magnitude.is_one() {
            target.push(name);
        } else {
            target.push(format!("{name}^{}", format_exponent(&magnitude)));
        }
    }
    let numerator = if numerator.is_empty() {
        "1".to_string()
    } else {
        numerator.join("*")
    };
    match denominator.len() {
        | 0 => numerator,
        // `M/L*T` reads as `(M/L)*T`; a product in the denominator needs
        // parentheses so the text parses back to the same dimension.
        | 1 => format!("{numerator}/{}", denominator[0]),
        | _ => format!("{numerator}/({})", denominator.join("*")),
    }
}

fn format_exponent(exponent: &BigRational) -> String {
    if exponent.denom().is_one() {
        exponent.numer().to_string()
    } else {
        format!("({})", format_rational(exponent))
    }
}

/// The SI symbol of a canonical base dimension, for display.
///
/// A base that is not one of the seven SI generators (a user-declared
/// `dimension` in a `DimEnv`, say) keeps its own name: inventing a symbol for
/// it would make the display ambiguous.
fn si_symbol(base: &str) -> &str {
    match base {
        | "Length" => "m",
        | "Mass" => "kg",
        | "Time" => "s",
        | "Current" => "A",
        | "Temperature" => "K",
        | "Amount" => "mol",
        | "Luminosity" => "cd",
        | other => other,
    }
}

/// The base dimensions and aliases known to a compilation.
///
/// The seven SI bases are always present; `dimension Currency` adds a base and
/// `dimension Area = L^2` adds an alias.
#[derive(Clone, Debug, serde::Serialize, serde::Deserialize)]
pub struct DimEnv {
    bases: Vec<String>,
    base_values: IndexMap<String, Dim>,
    short: IndexMap<String, String>,
    aliases: IndexMap<String, Dim>,
}

impl Default for DimEnv {
    fn default() -> Self {
        Self::si()
    }
}

impl DimEnv {
    /// The SI environment: seven bases plus the derived aliases of §4.1.1.
    #[must_use]
    pub fn si() -> Self {
        let mut env = Self {
            bases: Vec::new(),
            base_values: IndexMap::new(),
            short: IndexMap::new(),
            aliases: IndexMap::new(),
        };
        for (name, short) in [
            ("Length", "L"),
            ("Mass", "M"),
            ("Time", "T"),
            ("Current", "I"),
            ("Temperature", "Θ"),
            ("Amount", "Amt"),
            ("Luminosity", "Lum"),
        ] {
            env.bases.push(name.to_string());
            env.base_values.insert(name.to_string(), Dim::base(name));
            env.short.insert(name.to_string(), short.to_string());
        }
        for (alias, text) in [
            ("Area", "L^2"),
            ("Volume", "L^3"),
            ("Velocity", "L/T"),
            ("Acceleration", "L/T^2"),
            ("Frequency", "1/T"),
            ("Force", "M*L/T^2"),
            ("Pressure", "M/(L*T^2)"),
            ("Energy", "M*L^2/T^2"),
            ("Power", "M*L^2/T^3"),
            ("Momentum", "M*L/T"),
            ("Density", "M/L^3"),
            ("Charge", "I*T"),
            ("Voltage", "M*L^2/(I*T^3)"),
            ("Resistance", "M*L^2/(I^2*T^3)"),
            ("Capacitance", "I^2*T^4/(M*L^2)"),
            ("Inductance", "M*L^2/(I^2*T^2)"),
            ("MagneticFlux", "M*L^2/(I*T^2)"),
            ("MagneticFluxDensity", "M/(I*T^2)"),
            ("Entropy", "M*L^2/(T^2*Θ)"),
            ("MolarMass", "M/Amt"),
            ("Conductance", "1/Resistance"),
            ("Angle", "1"),
            ("SolidAngle", "1"),
        ] {
            if let Ok(dim) = env.parse(text) {
                env.aliases.insert(alias.to_string(), dim);
            }
        }
        env
    }

    /// Adds a user base dimension; returns false when the name already exists.
    pub fn define_base(
        &mut self,
        name: &str,
    ) -> bool {
        if self.lookup(name).is_some() {
            return false;
        }
        self.bases.push(name.to_string());
        self.base_values.insert(name.to_string(), Dim::base(name));
        true
    }

    /// Adds a source base while retaining its canonical declaration owner.
    pub fn define_nominal_base(
        &mut self,
        name: &str,
        owner: &str,
    ) -> bool {
        if self.lookup(name).is_some() {
            return false;
        }
        self.bases.push(name.to_string());
        self.base_values
            .insert(name.to_string(), Dim::nominal_base(owner, name));
        true
    }

    /// Adds a transparent alias such as `dimension Velocity = L/T`.
    pub fn define_alias(
        &mut self,
        name: &str,
        dim: Dim,
    ) {
        self.aliases.insert(name.to_string(), dim);
    }

    /// All base names in declaration order (SI first).
    #[must_use]
    pub fn base_names(&self) -> &[String] {
        &self.bases
    }

    /// All aliases in declaration order.
    #[must_use]
    pub fn aliases(&self) -> &IndexMap<String, Dim> {
        &self.aliases
    }

    /// Resolves a base name or alias.
    #[must_use]
    pub fn lookup(
        &self,
        name: &str,
    ) -> Option<Dim> {
        if let Some(dim) = self.base_values.get(name) {
            return Some(dim.clone());
        }
        for (canonical, short) in &self.short {
            if short == name {
                return Some(Dim::base(canonical));
            }
        }
        self.aliases.get(name).cloned()
    }

    /// Parses a dimension expression using this environment's names.
    ///
    /// # Errors
    ///
    /// Fails on unknown generators or malformed exponents.
    pub fn parse(
        &self,
        text: &str,
    ) -> Result<Dim, DimParseError> {
        let mut parser = DimTextParser::new(text);
        let dim = parser.parse_dim_with(self)?;
        parser.skip_space();
        if parser.rest().is_empty() {
            Ok(dim)
        } else {
            Err(DimParseError::Trailing(parser.rest().to_string()))
        }
    }

    /// Renders a dimension the way a diagnostic or `show` should.
    ///
    /// Prefers the shortest known alias (`Energy` over `M*L^2/T^2`), otherwise
    /// prints single-letter bases, which is the surface syntax of §2.5.1.
    #[must_use]
    pub fn format(
        &self,
        dim: &Dim,
    ) -> String {
        let short = self.format_short(dim);
        let mut best: Option<(&str, usize)> = None;
        for (alias, value) in &self.aliases {
            if value == dim {
                let len = alias.chars().count();
                if best.is_none_or(|(_, best_len)| len < best_len) {
                    best = Some((alias, len));
                }
            }
        }
        match best {
            | Some((alias, len)) if len < short.chars().count() => alias.to_string(),
            | _ => short,
        }
    }

    /// Renders with single-letter SI bases and canonical user bases.
    #[must_use]
    pub fn format_short(
        &self,
        dim: &Dim,
    ) -> String {
        render(dim, |atom| {
            match atom {
                | Atom::Base(name) => {
                    self.short
                        .get(&**name)
                        .cloned()
                        .unwrap_or_else(|| (*name).to_string())
                },
                | Atom::Nominal(base) => base.display_name().to_string(),
                | Atom::Var(id) => format!("d{id}"),
            }
        })
    }
}

/// Error from parsing a dimension expression.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum DimParseError {
    /// A generator name is not a base dimension or alias.
    UnknownName(String),
    /// The text ended in the middle of an expression.
    UnexpectedEnd,
    /// Characters were left over after a complete expression.
    Trailing(String),
    /// An exponent was not an integer or `(a/b)`.
    BadExponent(String),
}

impl fmt::Display for DimParseError {
    fn fmt(
        &self,
        f: &mut fmt::Formatter<'_>,
    ) -> fmt::Result {
        match self {
            | Self::UnknownName(name) => write!(f, "unknown dimension `{name}`"),
            | Self::UnexpectedEnd => f.write_str("unexpected end of dimension expression"),
            | Self::Trailing(text) => write!(f, "unexpected `{text}` after dimension expression"),
            | Self::BadExponent(text) => write!(f, "invalid dimension exponent `{text}`"),
        }
    }
}

impl std::error::Error for DimParseError {}

struct DimTextParser<'a> {
    text: &'a str,
    pos: usize,
    transport: bool,
}

impl<'a> DimTextParser<'a> {
    fn new(text: &'a str) -> Self {
        Self {
            text,
            pos: 0,
            transport: false,
        }
    }

    fn rest(&self) -> &'a str {
        &self.text[self.pos..]
    }

    fn skip_space(&mut self) {
        while let Some(c) = self.rest().chars().next() {
            if c.is_whitespace() {
                self.pos += c.len_utf8();
            } else {
                break;
            }
        }
    }

    fn peek(&mut self) -> Option<char> {
        self.skip_space();
        self.rest().chars().next()
    }

    fn bump(&mut self) -> Option<char> {
        let c = self.peek()?;
        self.pos += c.len_utf8();
        Some(c)
    }

    fn parse_dim(&mut self) -> Result<Dim, DimParseError> {
        let env = DimEnv::si();
        self.parse_dim_with(&env)
    }

    fn parse_dim_with(
        &mut self,
        env: &DimEnv,
    ) -> Result<Dim, DimParseError> {
        let mut result = self.parse_factor(env)?;
        loop {
            match self.peek() {
                | Some('*') | Some('·') => {
                    self.bump();
                    result = result.mul(&self.parse_factor(env)?);
                },
                | Some('/') => {
                    self.bump();
                    result = result.div(&self.parse_factor(env)?);
                },
                | _ => return Ok(result),
            }
        }
    }

    fn parse_factor(
        &mut self,
        env: &DimEnv,
    ) -> Result<Dim, DimParseError> {
        let mut atom = self.parse_atom(env)?;
        if self.peek() == Some('^') {
            self.bump();
            let exponent = self.parse_exponent()?;
            atom = atom.pow(&exponent);
        }
        Ok(atom)
    }

    fn parse_atom(
        &mut self,
        env: &DimEnv,
    ) -> Result<Dim, DimParseError> {
        match self.peek() {
            | Some('(') => {
                self.bump();
                let inner = self.parse_dim_with(env)?;
                if self.peek() != Some(')') {
                    return Err(DimParseError::UnexpectedEnd);
                }
                self.bump();
                Ok(inner)
            },
            | Some('1') => {
                self.bump();
                Ok(Dim::one())
            },
            | Some(c) if c.is_alphabetic() || c == '_' => {
                let start = self.pos;
                while let Some(c) = self.peek() {
                    if c.is_alphanumeric() || c == '_' {
                        self.bump();
                    } else {
                        break;
                    }
                }
                let name = &self.text[start..self.pos];
                if self.transport {
                    if let Some(id) = name
                        .strip_prefix(VARIABLE_PREFIX)
                        .and_then(|id| id.parse().ok())
                    {
                        return Ok(Dim::var(id));
                    }
                    return Ok(Dim::from_transport_base(name));
                }
                env.lookup(name)
                    .ok_or_else(|| DimParseError::UnknownName(name.to_string()))
            },
            | Some(c) => Err(DimParseError::Trailing(c.to_string())),
            | None => Err(DimParseError::UnexpectedEnd),
        }
    }

    fn parse_exponent(&mut self) -> Result<BigRational, DimParseError> {
        let negative = if self.peek() == Some('-') {
            self.bump();
            true
        } else {
            false
        };
        if self.peek() == Some('(') {
            self.bump();
            let text_start = self.pos;
            while let Some(c) = self.peek() {
                if c == ')' {
                    break;
                }
                self.bump();
            }
            let inner = self.text[text_start..self.pos].trim().to_string();
            if self.peek() != Some(')') {
                return Err(DimParseError::BadExponent(inner));
            }
            self.bump();
            let value = match inner.split_once('/') {
                | Some((numerator, denominator)) => {
                    let numerator = parse_decimal(numerator)
                        .ok_or_else(|| DimParseError::BadExponent(inner.clone()))?;
                    let denominator = parse_decimal(denominator)
                        .ok_or_else(|| DimParseError::BadExponent(inner.clone()))?;
                    if denominator.is_zero() {
                        return Err(DimParseError::BadExponent(inner));
                    }
                    numerator / denominator
                },
                | None => parse_decimal(&inner).ok_or(DimParseError::BadExponent(inner))?,
            };
            return Ok(if negative { -value } else { value });
        }
        let start = self.pos;
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() {
                self.bump();
            } else {
                break;
            }
        }
        let text = &self.text[start..self.pos];
        if text.is_empty() {
            return Err(DimParseError::BadExponent(text.to_string()));
        }
        let value = BigInt::from(
            text.parse::<i64>()
                .map_err(|_| DimParseError::BadExponent(text.to_string()))?,
        );
        let value = BigRational::from_integer(value);
        Ok(if negative { -value } else { value })
    }
}

/// A mismatch between two dimensions, with the data a diagnostic needs.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct DimMismatch {
    /// The left-hand dimension after substitution.
    pub left: Dim,
    /// The right-hand dimension after substitution.
    pub right: Dim,
    /// `left / right`: the factors that differ.
    pub difference: Dim,
}

/// Solves dimension equations over the free abelian group (§4.3).
///
/// The unifier owns the substitution for dimension variables; the type
/// checker shares it across a whole module so that a variable bound in one
/// expression constrains every other use.
#[derive(Clone, Debug, Default)]
pub struct DimUnifier {
    subst: HashMap<u32, Dim>,
}

impl DimUnifier {
    /// A unifier with no bindings.
    #[must_use]
    pub fn new() -> Self {
        Self::default()
    }

    /// Resolves all bound variables in a dimension.
    #[must_use]
    pub fn resolve(
        &self,
        dim: &Dim,
    ) -> Dim {
        self.resolve_depth(dim, 0)
    }

    fn resolve_depth(
        &self,
        dim: &Dim,
        depth: u32,
    ) -> Dim {
        if depth > 64 {
            // A cycle here can only come from a bug in `bind`; returning the
            // unexpanded form keeps the checker from looping forever.
            return dim.clone();
        }
        dim.substitute(|id| {
            // Follow a chain of variable-to-variable bindings without
            // spending depth: a literal with many quantity elements unifies
            // that many fresh variables in a line.
            let mut value = self.subst.get(&id)?;
            for _ in 0..=self.subst.len() {
                let mut factors = value.factors();
                let next = match (factors.next(), factors.next()) {
                    | (Some((Atom::Var(next), exponent)), None) if exponent.is_one() => *next,
                    | _ => break,
                };
                match self.subst.get(&next) {
                    | Some(further) => value = further,
                    | None => break,
                }
            }
            Some(self.resolve_depth(value, depth + 1))
        })
    }

    /// Binds a variable to a dimension, checking for self-reference.
    ///
    /// # Errors
    ///
    /// Returns a mismatch carrying the offending dimension when the binding is
    /// circular (`d = d * L`), which no finite substitution can satisfy.
    pub fn bind(
        &mut self,
        id: u32,
        value: Dim,
    ) -> Result<(), DimMismatch> {
        let resolved = self.resolve(&value);
        if resolved.contains_var(id) {
            return Err(DimMismatch {
                left: Dim::var(id),
                right: resolved.clone(),
                difference: Dim::var(id).div(&resolved),
            });
        }
        self.subst.insert(id, resolved);
        Ok(())
    }

    /// Unifies two dimensions.
    ///
    /// Implements §4.3.1: repeatedly pick a variable from `left/right`, solve
    /// for it, and substitute until the quotient is `1` or only bases remain.
    ///
    /// # Errors
    ///
    /// Returns the residual mismatch when the dimensions cannot be made equal.
    pub fn unify(
        &mut self,
        left: &Dim,
        right: &Dim,
    ) -> Result<(), DimMismatch> {
        for _ in 0..256 {
            let quotient = self.resolve(left).div(&self.resolve(right));
            if quotient.is_one() {
                return Ok(());
            }
            let variable = quotient.factors().find_map(|(atom, exponent)| {
                match atom {
                    | Atom::Var(id) => Some((*id, exponent.clone())),
                    | Atom::Base(_) | Atom::Nominal(_) => None,
                }
            });
            let Some((id, exponent)) = variable else {
                let resolved_left = self.resolve(left);
                let resolved_right = self.resolve(right);
                return Err(DimMismatch {
                    difference: resolved_left.difference(&resolved_right),
                    left: resolved_left,
                    right: resolved_right,
                });
            };
            let rest = quotient.div(&Dim::var(id).pow(&exponent));
            // v^r = rest^-1  =>  v = rest^(-1/r)
            let solution = rest.pow(&(-exponent).recip());
            if solution.contains_var(id) {
                let resolved_left = self.resolve(left);
                let resolved_right = self.resolve(right);
                return Err(DimMismatch {
                    difference: resolved_left.difference(&resolved_right),
                    left: resolved_left,
                    right: resolved_right,
                });
            }
            self.bind(id, solution)?;
        }
        Err(DimMismatch {
            left: self.resolve(left),
            right: self.resolve(right),
            difference: self.resolve(left).difference(&self.resolve(right)),
        })
    }

    /// Number of bound variables, for tests and diagnostics.
    #[must_use]
    pub fn len(&self) -> usize {
        self.subst.len()
    }

    /// True when no variable has been bound.
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.subst.is_empty()
    }
}

/// The SI derived unit whose dimension is exactly `dim`, if any.
fn derived_si_symbol(dim: &Dim) -> Option<&'static str> {
    if !dim.is_concrete() || dim.is_one() {
        return None;
    }
    // (symbol, [M, L, T, I] exponents)
    const TABLE: [(&str, [i64; 4]); 11] = [
        ("N", [1, 1, -2, 0]),
        ("J", [1, 2, -2, 0]),
        ("W", [1, 2, -3, 0]),
        ("Pa", [1, -1, -2, 0]),
        ("C", [0, 0, 1, 1]),
        ("V", [1, 2, -3, -1]),
        ("Ω", [1, 2, -3, -2]),
        ("F", [-1, -2, 4, 2]),
        ("H", [1, 2, -2, -2]),
        ("Wb", [1, 2, -2, -1]),
        ("T", [1, 0, -2, -1]),
    ];
    let mut exponents = [0i64; 4];
    for (atom, exponent) in dim.factors() {
        let Atom::Base(name) = atom else {
            return None;
        };
        let slot = match name.as_ref() {
            | "Mass" => 0,
            | "Length" => 1,
            | "Time" => 2,
            | "Current" => 3,
            | _ => return None,
        };
        if !exponent.is_integer() {
            return None;
        }
        exponents[slot] = i64::try_from(exponent.numer()).ok()?;
    }
    TABLE
        .iter()
        .find(|(_, row)| *row == exponents)
        .map(|(symbol, _)| *symbol)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::rat::ratio;

    fn env() -> DimEnv {
        DimEnv::si()
    }

    #[test]
    fn canonical_forms_are_equal() {
        let env = env();
        assert_eq!(env.parse("L/T").unwrap(), env.parse("L*T^-1").unwrap());
        assert_eq!(env.parse("L^2").unwrap(), env.parse("L^(4/2)").unwrap());
        assert_eq!(env.parse("L/L").unwrap(), Dim::one());
        assert_eq!(env.parse("(L^2)^(1/2)").unwrap(), Dim::base("Length"));
        assert_eq!(
            env.parse("Energy").unwrap(),
            env.parse("M*L^2/T^2").unwrap()
        );
    }

    #[test]
    fn unification_solves_a_variable() {
        let env = env();
        let mut unifier = DimUnifier::new();
        let d = Dim::var(0);
        unifier
            .unify(&d, &env.parse("L/T").unwrap())
            .expect("solvable");
        assert_eq!(unifier.resolve(&d), env.parse("L/T").unwrap());
    }

    #[test]
    fn unification_forces_dimensionless() {
        let env = env();
        let mut unifier = DimUnifier::new();
        let d = Dim::var(0);
        unifier
            .unify(&d.pow(&ratio(2, 1)), &d.pow(&ratio(3, 1)))
            .expect("d = 1");
        assert_eq!(unifier.resolve(&d), Dim::one());
        assert_eq!(env.format(&unifier.resolve(&d)), "1");
    }

    #[test]
    fn unification_reports_mismatch() {
        let env = env();
        let mut unifier = DimUnifier::new();
        let error = unifier
            .unify(&env.parse("L").unwrap(), &env.parse("T").unwrap())
            .expect_err("incompatible");
        assert_eq!(error.left, env.parse("L").unwrap());
        assert_eq!(error.right, env.parse("T").unwrap());
        assert_eq!(error.difference, env.parse("L/T").unwrap());
    }

    #[test]
    fn unification_keeps_free_variables() {
        let env = env();
        let mut unifier = DimUnifier::new();
        unifier
            .unify(&Dim::var(0).mul(&Dim::var(1)), &env.parse("L").unwrap())
            .expect("one free variable");
        assert_eq!(
            unifier.resolve(&Dim::var(0)),
            Dim::base("Length").div(&Dim::var(1))
        );
    }

    #[test]
    fn formatting_prefers_short_aliases() {
        let env = env();
        assert_eq!(env.format(&env.parse("M*L^2/T^2").unwrap()), "Energy");
        assert_eq!(env.format(&env.parse("L/T").unwrap()), "L/T");
        assert_eq!(env.format(&Dim::one()), "1");
    }

    #[test]
    fn plain_form_uses_canonical_names() {
        let env = env();
        let dim = env.parse("M*L^2/T^2").unwrap();
        assert_eq!(dim.to_plain_string(), "Length^2*Mass/Time^2");
        assert_eq!(Dim::parse_plain(&dim.to_plain_string()).unwrap(), dim);
    }

    /// Value display uses SI symbols, and a rational exponent is parenthesised:
    /// a Brownian increment over `dt` is `s^(1/2)`, and the old `s^1` spelling
    /// silently claimed the wrong dimension (§8.9.1).
    #[test]
    fn si_symbols_keep_rational_exponents() {
        let half = ratio(1, 2);
        let minus_half = ratio(-1, 2);
        let three_halves = ratio(3, 2);
        let time = Dim::base("Time");
        assert_eq!(time.pow(&half).to_si_symbol_string(), "s^(1/2)");
        assert_eq!(time.pow(&minus_half).to_si_symbol_string(), "1/s^(1/2)");
        assert_eq!(time.to_si_symbol_string(), "s");
        let acceleration = Dim::base("Length").div(&time.pow(&ratio(2, 1)));
        assert_eq!(acceleration.to_si_symbol_string(), "m/s^2");
        assert_eq!(
            Dim::base("Length").pow(&three_halves).to_si_symbol_string(),
            "m^(3/2)"
        );
        let energy = Dim::base("Mass")
            .mul(&Dim::base("Length").pow(&ratio(2, 1)))
            .div(&time.pow(&ratio(2, 1)));
        assert_eq!(energy.to_si_symbol_string(), "m^2*kg/s^2");
        // §5.4.3: display prefers the named derived unit when it is exact.
        assert_eq!(energy.to_display_si_string(), "J");
        let current = Dim::base("Current");
        let voltage = energy.div(&time).div(&current);
        assert_eq!(voltage.to_display_si_string(), "V");
        assert_eq!(voltage.div(&current).to_display_si_string(), "Ω");
        let force = energy.div(&Dim::base("Length"));
        assert_eq!(force.to_display_si_string(), "N");
        // Not guessed: frequency, a product with a base unit, or a fraction.
        assert_eq!(time.inverse().to_display_si_string(), "1/s");
        assert_eq!(
            energy.mul(&Dim::base("Length")).to_display_si_string(),
            energy.mul(&Dim::base("Length")).to_si_symbol_string()
        );
        assert_eq!(acceleration.to_display_si_string(), "m/s^2");
        assert_eq!(time.pow(&half).to_display_si_string(), "s^(1/2)");
        assert_eq!(Dim::one().to_si_symbol_string(), "");
        // A dimension variable has no SI symbol; the display keeps it opaque.
        assert_eq!(Dim::var(7).to_si_symbol_string(), "d7");
        // The parenthesised form round-trips through the plain parser once the
        // symbols are mapped back to the canonical generators.
        let plain = time.pow(&half).to_plain_string();
        assert_eq!(plain, "Time^(1/2)");
        assert_eq!(Dim::parse_plain(&plain).unwrap(), time.pow(&half));
    }
}
